private TreeNode<T> rotateRight(TreeNode<T> node){
	/* This method takes as input a node to rotate and returns a new parent of the node. */
	if(node == null){
		throw new IllegalArgumentException("The node cannot be null");
	}
	TreeNode<T> parent = node.getParent();
	TreeNode<T> grandParent = parent.getParent();
	if(grandParent == null){
		return node;
	}
	if(node == parent.getRightChild()){
		grandParent.setRightChild(node);
		node.setParent(grandParent);
		parent.setParent(node);
		node.setLeftChild(parent);
		grandParent.setLeftChild(node.getRightChild());
		node.setRightChild(null);
		return node;
	}else{
		grandParent.setLeftChild(node);
		node.setParent(grandParent);
		parent.setParent(node);
		node.setLeftChild(parent);
		grandParent.setRightChild(node.getLeftChild());
		node.setLeftChild(null);
		return node;
	}
}

