/**
 * Perform variable substitution on <code>value</code> using the values found in <code>props</code>.
 */
private static String substituteVariables(String value, Properties props) {
	Matcher matcher = Pattern.compile("\\$\\{([a-zA-Z0-9_]+)\\}").matcher(value);
	while (matcher.find()) {
		String variableName = matcher.group(1);
		String variableValue = props.getProperty(variableName);
		if (variableValue != null) {
			value = value.replaceAll("\\$\\{" + variableName + "\\}", variableValue);
		}
	}
