	// Step 1: Check if the desired capacity is valid
	if (desiredCapacity < 0) {
		throw new IllegalArgumentException("Desired capacity must be >= 0");
	}

	// Step 2: Initialize the closest prime number to the desired capacity
	int closestPrime = 0;

	// Step 3: Loop through the prime numbers until we find one that is close enough to the desired capacity
	for (int i = 2; i < desiredCapacity; i++) {
		if (isPrime(i)) {
			closestPrime = i;
		}
	}

	// Step 4: Return the closest prime number
	return closestPrime;
}

