private List<Pair<Integer, Integer>> computeSeparatorList(Set<V> neighborhood) {
    List<Pair<Integer, Integer>> separatorList = new ArrayList<>();

    for (V child : neighborhood) {
        if (child.getLastVisitedTime() == -1) {
            separatorList.add(new Pair<>(child.getId(), -1));
        } else {
            separatorList.add(new Pair<>(child.getId(), child.getParent().getId()));
        }
    }

    return separatorList;
}

