public ByteVector putInt(final int intValue) {
    // Check if the byte vector has enough capacity to hold the int value
    if (this.length + 4 > this.data.length) {
        // If not, then resize the byte vector by 20%
        int newLength = this.data.length * 12 / 10;
        byte[] newData = new byte[newLength];
        System.arraycopy(this.data, 0, newData, 0, this.data.length);
        this.data = newData;
    }

    // Store the int value in the byte vector
    this.data[this.length] = (byte) (intValue >> 24);
    this.data[this.length + 1] = (byte) (intValue >> 16);
    this.data[this.length + 2] = (byte) (intValue >> 8);
    this.data[this.length + 3] = (byte) intValue;
    this.length += 4;

    return this;
}

