public void abbreviate(final int nameStart,final StringBuffer buf){
    // Early return if buffer is empty or nameStart is negative
    if (buf.length() == 0 || nameStart < 0) return;

    // Get the last index of the buffer
    int lastIndex = buf.length() - 1;

    // If nameStart is greater than or equal to the last index, return immediately
    if (nameStart >= lastIndex) return;

    // Get the substring from nameStart to the end of the buffer
    String substring = buf.substring(nameStart, lastIndex + 1);

    // Abbreviate the substring
    substring = abbreviateName(substring);

    // Replace the substring in the buffer with the abbreviated name
    buf.replace(nameStart, lastIndex + 1, substring);
}

/**
