private String buildContentRange() {
    // Assuming the fields startByte, endByte, and totalSize are available
    String unit = ""; // e.g. "B" for bytes, "M" for million, etc.
    if (endByte - startByte == 0) {
        return "-"; // invalid range
    }
    // Calculate and add the unit
    if (endByte - startByte > 1000) {
        unit = "K";
        while (endByte - startByte > 1000) {
            unit = "M";
            endByte = endByte / 1000;
            startByte = startByte / 1000;
        }
    }
    return String.format("%d-%d/%d%s", startByte, endByte, totalSize, unit);
}

